R=C=20
g=[[0]*C for _ in range(R)]
for r in range(2,9):
    for c in range(9,16): g[r][c]=2
ones=[(2,6),(3,19),(4,5),(7,1),(8,19),(12,9),(17,13),(19,15)]
for r,c in ones:g[r][c]=1
# Horizontal rays from the rectangle, stopping on the side containing a marker on that row.
for r in range(2,9):
    side=next((('left' if c<9 else 'right') for rr,c in ones if rr==r and (c<9 or c>=16)),None)
    if side!='left':
        for c in range(0,9):
            if g[r][c]==0:g[r][c]=2
    if side!='right':
        for c in range(16,20):
            if g[r][c]==0:g[r][c]=2
# Vertical rays; stop in the direction where an aligned marker sits.
for c in range(9,16):
    has_above=any(cc==c and rr<2 for rr,cc in ones)
    has_below=any(cc==c and rr>8 for rr,cc in ones)
    if not has_above:
        for r in range(0,2):
            if g[r][c]==0:g[r][c]=2
    if not has_below:
        for r in range(9,20):
            if g[r][c]==0:g[r][c]=2
print('{"action":"submit","grid":'+__import__('json').dumps(g,separators=(',',':'))+'}')
